const symbols=new Set(['SOL','BTC','ETH','XRP','BNB','DOGE']);
const intervals=new Set(['1m','5m','15m','1h','6h','1d']);
const cache=new Map();
export function validateCandleQuery(url){const u=new URL(url,'https://local.invalid'),symbol=(u.searchParams.get('symbol')||'SOL').toUpperCase(),interval=u.searchParams.get('interval')||'1h';return symbols.has(symbol)&&intervals.has(interval)?{symbol,interval}:null;}
export async function getCandles(symbol,interval){const key=symbol+interval,old=cache.get(key);if(old&&Date.now()-old.time<30000)return old.data;const r=await fetch(`https://data-api.binance.vision/api/v3/klines?symbol=${symbol}USDT&interval=${interval}&limit=240`,{signal:AbortSignal.timeout(9000)});if(!r.ok)throw Error('Reference source unavailable');const rows=await r.json();if(!Array.isArray(rows))throw Error('Invalid source response');const data={symbol,interval,asOf:new Date().toISOString(),source:'Binance public exchange reference',candles:rows.map(c=>({time:c[0],open:+c[1],high:+c[2],low:+c[3],close:+c[4],volume:+c[5]}))};cache.set(key,{time:Date.now(),data});return data;}
export default async function handler(req,res){res.setHeader('content-type','application/json');if(req.method!=='GET'){res.statusCode=405;res.end(JSON.stringify({error:'Method not allowed'}));return;}const query=validateCandleQuery(req.url);if(!query){res.statusCode=400;res.end(JSON.stringify({error:'Unsupported market or candle interval'}));return;}try{res.setHeader('Cache-Control','s-maxage=25, stale-while-revalidate=30');res.end(JSON.stringify(await getCandles(query.symbol,query.interval)));}catch{res.statusCode=503;res.end(JSON.stringify({error:'Candle reference temporarily unavailable'}));}}
